import{_ as t,o as e,c as n,a2 as i}from"./chunks/framework.BBd5PKnH.js";const g=JSON.parse('{"title":"Database vs Data Lake vs Data Warehouse","description":"","frontmatter":{},"headers":[],"relativePath":"notes/database_datalake_datawarehouse.md","filePath":"notes/database_datalake_datawarehouse.md"}'),s={name:"notes/database_datalake_datawarehouse.md"};function h(r,a,l,o,d,u){return e(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="database-vs-data-lake-vs-data-warehouse" tabindex="-1">Database vs Data Lake vs Data Warehouse <a class="header-anchor" href="#database-vs-data-lake-vs-data-warehouse" aria-label="Permalink to &quot;Database vs Data Lake vs Data Warehouse&quot;">​</a></h1><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><ul><li>Theo mô hình <strong>OLTP</strong> (Online Transaction Processing).</li><li>Dữ liệu được đọc/ghi và thay đổi theo thời gian thực.</li></ul><h2 id="data-lake" tabindex="-1">Data Lake <a class="header-anchor" href="#data-lake" aria-label="Permalink to &quot;Data Lake&quot;">​</a></h2><ul><li>Theo mô hình <strong>OLAP</strong> (Online Analytical Processing) — hỗ trợ việc viết các câu query phức tạp trên tập dữ liệu quá khứ.</li><li>Dữ liệu lưu trong data lake về cơ bản giống dữ liệu gốc trong database (thường ở dạng thô, chưa qua xử lý nhiều).</li></ul><h2 id="data-warehouse" tabindex="-1">Data Warehouse <a class="header-anchor" href="#data-warehouse" aria-label="Permalink to &quot;Data Warehouse&quot;">​</a></h2><ul><li>Cũng theo mô hình <strong>OLAP</strong>.</li></ul><h3 id="data-mart" tabindex="-1">Data Mart <a class="header-anchor" href="#data-mart" aria-label="Permalink to &quot;Data Mart&quot;">​</a></h3><ul><li>Mỗi data warehouse có thể chứa nhiều <strong>data mart</strong> khác nhau — mỗi data mart phục vụ một nhóm nghiệp vụ/phòng ban cụ thể (ví dụ: marketing, tài chính...).</li></ul><h2 id="vai-tro-cac-nhan-su-lien-quan" tabindex="-1">Vai trò các nhân sự liên quan <a class="header-anchor" href="#vai-tro-cac-nhan-su-lien-quan" aria-label="Permalink to &quot;Vai trò các nhân sự liên quan&quot;">​</a></h2><ul><li><strong>Data Engineer</strong>: xây dựng các <strong>data pipeline</strong> để ingest dữ liệu từ database sang data lake, và xử lý (process) dữ liệu từ data lake sang data warehouse.</li><li><strong>Data Analyst</strong>: xử lý số liệu ở data lake và data warehouse. Đây thường là người hiểu rõ nghiệp vụ (business) nhất, biết cần dùng số liệu nào để tạo ra báo cáo, có thể tự viết SQL để xử lý dữ liệu đơn giản. Với các trường hợp cần xử lý dữ liệu phức tạp hơn, họ sẽ phối hợp với Data Engineer — Data Engineer sẽ dựa theo nhu cầu của Data Analyst để xây dựng pipeline phù hợp.</li><li><strong>Data Scientist</strong>: sử dụng nhiều loại dữ liệu khác nhau, thử nghiệm để tìm ra dữ liệu phù hợp phục vụ việc xây dựng mô hình (model).</li></ul>',11)])])}const p=t(s,[["render",h]]);export{g as __pageData,p as default};
